document.getElementById('year').textContent=new Date().getFullYear();
const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');document.querySelector('nav').classList.toggle('open',open)});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}));
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('[name="service"]').value=a.dataset.service}));
document.getElementById('quote-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const message=`Hello Bright Ocean Logistics, I would like a shipping quote.\n\nName: ${d.get('name')}\nPhone: ${d.get('phone')}\nShipping method: ${d.get('service')}\nDestination: ${d.get('destination')}\nCargo details: ${d.get('cargo')}`;window.open('https://wa.me/2348060227854?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')});
document.querySelector('.copy-address').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('[lang="zh"]').textContent);document.getElementById('copy-status').textContent='Address copied.'}catch{document.getElementById('copy-status').textContent='Please select and copy the address above.'}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'prepare_shipping_quote',description:'Fill the visible shipping quote form for review. Does not send a message or contact the company.',inputSchema:{type:'object',properties:{name:{type:'string'},phone:{type:'string'},service:{type:'string',enum:['Sea shipping','Air freight','Help me choose']},destination:{type:'string',enum:['Lagos','Onitsha','Other Nigerian city']},cargo:{type:'string'}},required:['name','phone','service','destination','cargo'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['name','phone','service','destination','cargo'].includes(k))||['name','phone','cargo'].some(k=>typeof input[k]!=='string'||!input[k].trim())||input.name.length>100||input.phone.length>30||input.cargo.length>2000||!['Sea shipping','Air freight','Help me choose'].includes(input.service)||!['Lagos','Onitsha','Other Nigerian city'].includes(input.destination))throw new Error('Provide valid quote details.');for(const key of ['name','phone','service','destination','cargo'])document.querySelector(`[name="${key}"]`).value=input[key];document.getElementById('quote').scrollIntoView();return {status:'prepared',message:'Review the form and continue on WhatsApp to send.'};}})).catch(()=>{});}catch{}}
